  username: Joi.string().min(3).max(30).alphanum().required(),
  email: Joi.string().email().required(),
  password: Joi.string().min(12).max(128).required(),
}).unknown(false); // disallow extra fields

function validate(schema) {
  return (req, res, next) => {
    const data = ['GET', 'DELETE'].includes(req.method)
      ? req.query
      : req.body;

    const { error, value } = schema.validate(data, {
      abortEarly: false,
      stripUnknown: true,  // remove unexpected fields
    });

    if (error) {
      // Avoid exposing internals of validation library
      return res.status(400).json({
        error: {
          message: 'Invalid input',
          details: error.details.map(d => d.message),
        },
      });
    }

    // Use validated/sanitized data instead of raw input
    req.validated = value;
    next();
  };
}

// Usage in a route:
app.post('/users', validate(createUserSchema), async (req, res, next) => {
  try {
    const { username, email, password } = req.validated;
    // ...
  } catch (err) {
    next(err);
  }
});
```

**Security benefits:**
- Mitigates injection attacks and type confusion.
- Prevents parameter pollution and unexpected extra fields being used.

